<template>
  <div class="bot-match-container">
    <t-loading :loading="isLoading">
      <!-- 统一状态面板 -->
      <div v-if="!canShowMatch" class="status-panel-container">
        <div class="status-panel">
          <!-- 动态图标 -->
          <div :class="['status-icon', IsBotStatusRunning(botStatus) ? 'processing-icon' : 'completed-icon']">
            {{ IsBotStatusRunning(botStatus) ? '⏳' : '✅' }}
          </div>

          <!-- 动态消息 -->
          <p>{{ (IsBotStatusRunning(botStatus) ? '您的对局正在处理中，请稍候...' : '评测已结束') }}</p>

          <!-- 显示评测状态 -->
          <p class="status-info">当前状态: {{ GetBotStatusStr(botStatus) }}</p>

          <!-- 触发者：可能来自某个用户，也可能是系统发起 -->
          <div class="inserter-info">
            <span class="inserter-label">触发者：</span>
            <t-tag v-if="isSystemTriggered" theme="default" variant="light">系统</t-tag>
            <template v-else>
              <t-avatar shape="round" size="20px" :image="inserterAvatarUrl" :hide-on-load-failed="false" />
              <t-button variant="text" @click="handleClickInserter">{{ inserterDisplayName }}</t-button>
            </template>
          </div>

          <!-- 显示botMessage（如果有） -->
          <p v-if="botMessage" class="message-info">{{ botMessage }}</p>
        </div>
      </div>

      <!-- 游戏内容 -->
      <div v-else>
        <!-- 状态信息 -->
        <div class="match-status-container">
          <div class="status-section">
            <h3>评测状态</h3>
            <p class="status-info">当前状态: {{ GetBotStatusStr(botStatus) }}</p>
          </div>
          <!-- 触发者：与「评测中」面板保持同一口径 -->
          <div class="inserter-info">
            <span class="inserter-label">触发者：</span>
            <t-tag v-if="isSystemTriggered" theme="default" variant="light">系统</t-tag>
            <template v-else>
              <t-avatar shape="round" size="20px" :image="inserterAvatarUrl" :hide-on-load-failed="false" />
              <t-button variant="text" @click="handleClickInserter">{{ inserterDisplayName }}</t-button>
            </template>
          </div>
          <div v-if="botMessage" class="message-section">
            <p class="message-info">{{ botMessage }}</p>
          </div>
        </div>

        <!-- 动态加载游戏组件 -->
        <component :is="gameComponent" v-if="gameComponent" v-model:game-data="gameData" />

        <!-- 无效游戏提示 -->
        <div v-else class="game-not-found">
          <div class="error-icon">❌</div>
          <h2>游戏未找到</h2>
          <p>无效的游戏类型或游戏不存在。</p>
        </div>
      </div>
    </t-loading>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, onUnmounted, defineAsyncComponent, computed } from "vue";
import { useRoute, useRouter } from "vue-router";
import { GetBotMatch, IsBotStatusRunning, IsBotMatchTriggeredBySystem, BotStatus, GetBotStatusStr, ParseBotMatchDetail, ConvertToGenericGameData } from "@/apis/bot";
import type { BotMatchDetailView, GenericGameData } from "@/types/bot";
import { GetAvatarUrl } from "@/util/avatar.ts";
import { handleGotoUsername } from "@/util/router";
import { ShowErrorTips } from "@/util/tips";
import { useCurrentInstance } from "@/util";

// 动态导入游戏组件
const gameComponents = {
  gomoku: defineAsyncComponent(() => import("./game/Gomoku.vue")),
  tictactoe: defineAsyncComponent(() => import("./game/TicTacToe.vue")),
};

const route = useRoute();
const router = useRouter();
const gameKey = ref("");
const matchId = ref(-1);

// 加载状态
const isLoading = ref(true);
const { globalProperties } = useCurrentInstance();
const botStatus = ref<BotStatus>(BotStatus.BotStatusUnknown);
const botMessage = ref<string>("");
const canShowMatch = ref(false);
let refreshTimer: number | null = null;

// 触发者：后端 inserter 为 0 表示系统发起，此时没有可跳转的用户
const matchInserter = ref(0);
const inserterUsername = ref("");
const inserterNickname = ref("");
const inserterEmail = ref("");
const isSystemTriggered = computed(() => IsBotMatchTriggeredBySystem(matchInserter.value));
const inserterAvatarUrl = computed(() => GetAvatarUrl(inserterUsername.value, inserterEmail.value));
const inserterDisplayName = computed(() => inserterNickname.value || inserterUsername.value);

const handleClickInserter = async () => {
  if (isSystemTriggered.value) {
    return;
  }
  await handleGotoUsername(router, inserterUsername.value);
};

// 通用游戏数据
const gameData = ref<GenericGameData>({
  id: "",
  gameKey: "",
  gameTitle: "",
  status: BotStatus.BotStatusUnknown,
  infoData: {},
  paramData: {},
  agents: [],
});

// 根据gameKey动态加载对应的游戏组件
const gameComponent = computed(() => {
  const key = gameKey.value.toLowerCase();
  return gameComponents[key as keyof typeof gameComponents] || null;
});

// 触发者信息在首次加载与轮询刷新里都要更新，抽成一个函数避免两处口径不一致
function applyInserter(detail: BotMatchDetailView) {
  matchInserter.value = detail.inserter;
  inserterUsername.value = detail.inserterUsername;
  inserterNickname.value = detail.inserterNickname;
  inserterEmail.value = detail.inserterEmail;
}

// 获取游戏数据
async function fetchData() {
  isLoading.value = true;

  try {
    // 同时调用两个 API 获取完整数据
    const [matchResponse] = await Promise.all([
      GetBotMatch(gameKey.value, matchId.value),
    ]);

    if (matchResponse.code !== 0) {
      ShowErrorTips(globalProperties, matchResponse.code);
      return;
    }

    if (matchResponse.data) {
      // 合并两个 API 返回的数据
      const mergedData = {
        ...matchResponse.data,
      };

      // 使用解析函数处理服务器返回的数据
      const matchDetail = ParseBotMatchDetail(mergedData);
      botStatus.value = matchDetail.status;
      botMessage.value = IsBotStatusRunning(botStatus.value) ? "游戏进行中" : matchDetail.message || "";
      applyInserter(matchDetail);

      // 根据状态更新显示逻辑
      canShowMatch.value = matchDetail.status === BotStatus.BotStatusRunning || matchDetail.status === BotStatus.BotStatusFinish;

      // 转换为通用游戏数据
      if (canShowMatch.value) {
        gameData.value = ConvertToGenericGameData(matchDetail);
        console.log("BotMatch: 游戏数据已更新:", gameData.value);
      }

      // 启动定时刷新（如果游戏仍在运行中）
      startAutoRefresh();
    }
  } catch (error) {
    console.error("获取游戏对局数据失败:", error);
    ShowErrorTips(globalProperties, "获取游戏对局数据失败");
  } finally {
    isLoading.value = false;
  }
}

// 缓存上一次的 param 数据，避免不必要的更新
let lastParamHash = "";

// 获取最新的游戏参数
async function fetchMatchParam() {
  try {
    // 同时调用两个 API 获取完整数据
    const [matchResponse] = await Promise.all([
      GetBotMatch(gameKey.value, matchId.value),
    ]);

    if (matchResponse.code === 0 && matchResponse.data) {
      // 合并两个 API 返回的数据
      const mergedData = {
        ...matchResponse.data,
      };

      const matchDetail = ParseBotMatchDetail(mergedData);
      botStatus.value = matchDetail.status;
      applyInserter(matchDetail);

      // 根据状态更新显示逻辑
      canShowMatch.value = matchDetail.status === BotStatus.BotStatusRunning || matchDetail.status === BotStatus.BotStatusFinish;

      if (canShowMatch.value) {
        // 检查 param 是否存在
        if (matchDetail.paramData) {
          // 计算 param 的哈希值，用于检测是否真的发生了变化
          const paramHash = JSON.stringify(matchDetail.paramData);

          // 如果 param 没有变化，直接返回，避免不必要的更新
          if (paramHash === lastParamHash) {
            console.log("BotMatch: param 未变化，跳过更新");
            // 如果游戏已结束，停止自动刷新
            if (!IsBotStatusRunning(matchDetail.status)) {
              stopAutoRefresh();
            }
            return;
          }

          // 更新哈希值
          lastParamHash = paramHash;

          // 转换为通用游戏数据
          gameData.value = ConvertToGenericGameData(matchDetail);
          console.log("BotMatch: 游戏数据已刷新:", gameData.value);
        }
      }

      // 如果游戏已结束，停止自动刷新
      if (!IsBotStatusRunning(matchDetail.status)) {
        stopAutoRefresh();
      }
    }
  } catch (error) {
    console.error("获取游戏参数失败:", error);
  }
}

// 启动自动刷新
function startAutoRefresh() {
  stopAutoRefresh();

  if (IsBotStatusRunning(botStatus.value)) {
    console.log("BotMatch: 启动自动刷新，间隔1秒");
    refreshTimer = window.setInterval(fetchMatchParam, 1000);
  } else {
    console.log("BotMatch: 游戏状态非Running，不启动自动刷新");
  }
}

// 停止自动刷新
function stopAutoRefresh() {
  if (refreshTimer !== null) {
    clearInterval(refreshTimer);
    refreshTimer = null;
  }
}

// 组件挂载时初始化
onMounted(async () => {
  if (Array.isArray(route.params.gameKey)) {
    gameKey.value = route.params.gameKey[0];
  } else {
    gameKey.value = route.params.gameKey as string;
  }

  if (Array.isArray(route.params.matchId)) {
    matchId.value = Number(route.params.matchId[0]);
  } else {
    matchId.value = Number(route.params.matchId);
  }

  await fetchData();
});

// 组件卸载时清理定时器
onUnmounted(() => {
  stopAutoRefresh();
});
</script>

